import { createSignal } from "solid-js"
import type { Context } from "@opencode/plugin/gui"
import { speak, speakPlan, speakPrepare, speakCancel, debugLog } from "./client"
import { fromBase64 } from "./recorder"
import { readSettings } from "./settings-store"

// Read-aloud player: ONE continuous audio for the whole reply, generated by a
// single Edge TTS request. No chunks, no seams, no character limit and no
// mid-sentence stalls. Playback starts once the full file is ready; the player
// shows a spinner meanwhile.

export type PlayerPhase = "idle" | "planning" | "speaking" | "paused" | "error"

export interface PlayerBar {
  value: number
  start: number
  end: number
}

const [phase, setPhase] = createSignal<PlayerPhase>("idle")
const [elapsed, setElapsed] = createSignal(0)
const [total, setTotal] = createSignal<number | null>(null)
const [error, setError] = createSignal("")

export function playerPhase(): PlayerPhase {
  return phase()
}

export function playerElapsed(): number {
  return elapsed()
}

export function playerTotal(): number | null {
  return total()
}

/** Kept for the player view; single-file playback never "pumps" chunks. */
export function playerPumping(): boolean {
  return false
}

export function playerError(): string {
  return error()
}

export function playerActive(): boolean {
  return phase() !== "idle"
}

let bars: PlayerBar[] = []

export function playerBars(): readonly PlayerBar[] {
  return bars
}

let audioEl: HTMLAudioElement | null = null
let objectUrl: string | null = null
let mediaNode: MediaElementAudioSourceNode | null = null
let analyser: AnalyserNode | null = null
let waveContext: AudioContext | null = null
let generation = 0
let controller: AbortController | null = null
let clockRunning = false
let lastText = ""
let lastContext: Context | null = null
let lastSessionKey = ""
let utterance: SpeechSynthesisUtterance | null = null
let streamId: string | null = null
let systemStart = 0
let systemPausedAt = 0
let systemPausedTotal = 0
let systemKeepAlive: number | null = null

// One window at a time owns playback, so two windows cannot speak together.
const WINDOW_ID = Math.random().toString(36).slice(2)
const LOCK_KEY = "nakamura-voice:playback-owner"
let heartbeat: number | null = null

function acquireLock(): boolean {
  try {
    const raw = localStorage.getItem(LOCK_KEY)
    if (raw) {
      const [owner, at] = raw.split("|")
      if (owner && owner !== WINDOW_ID && Date.now() - Number(at) < 2500) return false
    }
    renewal()
    return true
  } catch {
    return true
  }
}

function renewal(): void {
  try {
    localStorage.setItem(LOCK_KEY, `${WINDOW_ID}|${Date.now()}`)
  } catch {
    // storage unavailable
  }
}

function releaseLock(): void {
  if (heartbeat !== null) {
    window.clearInterval(heartbeat)
    heartbeat = null
  }
  try {
    const raw = localStorage.getItem(LOCK_KEY)
    if (raw?.startsWith(`${WINDOW_ID}|`)) localStorage.removeItem(LOCK_KEY)
  } catch {
    // storage unavailable
  }
}

function describeError(reason: unknown): string {
  if (reason instanceof Error) return reason.message
  if (reason && typeof reason === "object") {
    const record = reason as Record<string, unknown>
    if (typeof record.message === "string" && record.message) return record.message
    const data = record.data
    if (data && typeof data === "object" && typeof (data as Record<string, unknown>).message === "string") {
      return String((data as Record<string, unknown>).message)
    }
    try {
      return JSON.stringify(record)
    } catch {
      return String(reason)
    }
  }
  return String(reason)
}

function trace(ctx: Context, message: string): void {
  try {
    void debugLog(ctx, message)
  } catch {
    // logging must never break playback
  }
}

function releaseAudio(): void {
  if (audioEl) {
    audioEl.pause()
    audioEl.src = ""
    audioEl = null
  }
  if (objectUrl) URL.revokeObjectURL(objectUrl)
  objectUrl = null
  try {
    mediaNode?.disconnect()
    analyser?.disconnect()
  } catch {
    // already disconnected
  }
  mediaNode = null
  analyser = null
}

function reset(): void {
  if (systemKeepAlive !== null) {
    window.clearInterval(systemKeepAlive)
    systemKeepAlive = null
  }
  if (utterance) {
    try {
      window.speechSynthesis.cancel()
    } catch {
      // synthesis unavailable
    }
    utterance = null
  }
  releaseAudio()
  bars = []
  setElapsed(0)
  setTotal(null)
  setError("")
  clockRunning = false
}

function cancelStream(): void {
  if (!streamId) return
  const ctx = lastContext
  const id = streamId
  streamId = null
  if (ctx) void speakCancel(ctx, id)
}

export function stop(): void {
  generation++
  controller?.abort()
  controller = null
  cancelStream()
  releaseLock()
  reset()
  setPhase("idle")
  lastText = ""
  lastContext = null
  lastSessionKey = ""
}

export function stopIfSessionChanged(key: string | undefined): void {
  if (!playerActive() || !lastSessionKey) return
  if (key !== lastSessionKey) stop()
}

export async function play(ctx: Context, text: string): Promise<void> {
  const trimmed = text.trim()
  if (!trimmed) return
  if (playerActive() && lastText === trimmed && phase() !== "error") return
  stop()
  const gen = ++generation
  lastText = trimmed
  lastContext = ctx
  lastSessionKey = ctx.sessions.current()?.key ?? ""
  controller = new AbortController()
  if (!acquireLock()) {
    ctx.toast.show({ title: "Another OpenCode window is already reading aloud", variant: "error" })
    return
  }
  heartbeat = window.setInterval(renewal, 1000)
  setPhase("planning")
  primeAudioContext()
  try {
    if (readSettings().tts.engine === "system") {
      await startSystem(ctx, gen, trimmed)
      return
    }
    // Streaming first: playback starts as soon as the first bytes arrive.
    let streamed = false
    try {
      const prepared = await speakPrepare(ctx, trimmed)
      if (gen !== generation) {
        void speakCancel(ctx, prepared.id)
        return
      }
      streamId = prepared.id
      trace(ctx, `stream prepared url=${prepared.url}`)
      const audio = new Audio(prepared.url)
      audioEl = audio
      audio.preload = "auto"
      const syncTotal = (): void => {
        if (gen === generation && Number.isFinite(audio.duration) && audio.duration > 0) {
          setTotal(audio.duration)
        }
      }
      audio.addEventListener("loadedmetadata", syncTotal)
      audio.addEventListener("durationchange", syncTotal)
      audio.addEventListener("ended", () => {
        if (gen === generation) finish()
      })
      audio.addEventListener("error", () => {
        const mediaError = audio.error
        trace(ctx, `stream error code=${mediaError?.code} msg=${mediaError?.message}`)
        if (gen === generation) fail(ctx, new Error("The audio could not be played"))
      })
      audio.addEventListener("playing", () => trace(ctx, "event playing"))
      audio.addEventListener("stalled", () => trace(ctx, "event stalled"))
      audio.addEventListener("suspend", () => trace(ctx, "event suspend"))
      await audio.play()
      if (gen !== generation) return
      streamed = true
      syncTotal()
      setPhase("speaking")
      startClock(gen)
      trace(
        ctx,
        `play ok ct=${audio.currentTime.toFixed(2)} muted=${audio.muted} vol=${audio.volume} rs=${audio.readyState} dur=${audio.duration}`,
      )
      window.setTimeout(() => {
        trace(
          ctx,
          `t+1s ct=${audio.currentTime.toFixed(2)} paused=${audio.paused} muted=${audio.muted} vol=${audio.volume} rs=${audio.readyState} ns=${audio.networkState} ctx=${waveContext?.state ?? "-"} anal=${analyser ? "yes" : "no"}`,
        )
      }, 1000)
      return
    } catch (reason) {
      if (gen !== generation) return
      if (streamed) {
        fail(ctx, reason)
        return
      }
      streamId = null
      trace(ctx, `stream unavailable, falling back to buffer: ${describeError(reason)}`)
      // Streaming unavailable: fall back to a buffered file below.
    }

    const result = await speak(ctx, trimmed, controller.signal)
    if (gen !== generation) return
    if (!result.audioBase64) throw new Error("TTS returned empty audio")
    const bytes = fromBase64(result.audioBase64)
    objectUrl = URL.createObjectURL(new Blob([bytes], { type: result.mimeType || "audio/mpeg" }))
    const audio = new Audio(objectUrl)
    audioEl = audio
    audio.preload = "auto"
    audio.addEventListener("loadedmetadata", () => {
      if (gen === generation && Number.isFinite(audio.duration)) setTotal(audio.duration)
    })
    audio.addEventListener("ended", () => {
      if (gen === generation) finish()
    })
    audio.addEventListener("error", () => {
      const mediaError = audio.error
      trace(ctx, `buffered error code=${mediaError?.code} msg=${mediaError?.message}`)
      if (gen === generation) fail(ctx, new Error("The audio could not be played"))
    })
    await audio.play()
    if (gen !== generation) return
    if (Number.isFinite(audio.duration)) setTotal(audio.duration)
    setPhase("speaking")
    startClock(gen)
    trace(
      ctx,
      `buffered play ct=${audio.currentTime.toFixed(2)} muted=${audio.muted} vol=${audio.volume} rs=${audio.readyState} ctx=${waveContext?.state ?? "-"}`,
    )
  } catch (reason) {
    if (gen !== generation) return
    fail(ctx, reason)
  }
}

function contextRunning(context: AudioContext): boolean {
  return (context.state as AudioContextState) === "running"
}

function primeAudioContext(): void {
  try {
    waveContext ??= new AudioContext()
    if (waveContext.state !== "running") void waveContext.resume()
  } catch {
    // no audio context available; playback still uses the media element
  }
}

function attachAnalyser(audio: HTMLAudioElement): void {
  try {
    waveContext ??= new AudioContext()
    // A suspended context swallows all sound (the element plays silently).
    // Only reroute the element through Web Audio when the context is running;
    // otherwise leave it on the default output.
    if (!contextRunning(waveContext)) {
      void waveContext.resume()
      if (!contextRunning(waveContext)) {
        mediaNode = null
        analyser = null
        return
      }
    }
    mediaNode = waveContext.createMediaElementSource(audio)
    analyser = waveContext.createAnalyser()
    analyser.fftSize = 256
    mediaNode.connect(analyser)
    analyser.connect(waveContext.destination)
    void waveContext.resume()
  } catch {
    // Waveform is cosmetic; playback continues without it.
    mediaNode = null
    analyser = null
  }
}

async function startSystem(ctx: Context, gen: number, text: string): Promise<void> {
  try {
    const plan = await speakPlan(ctx, text)
    if (gen !== generation) return
    const clean = plan.chunks.join(" ").trim()
    if (!clean) throw new Error("Nothing to read aloud")
    if (!("speechSynthesis" in window)) throw new Error("Speech synthesis is not available")
    window.speechSynthesis.cancel()
    const utter = new SpeechSynthesisUtterance(clean)
    const voice = pickSystemVoice()
    if (voice) utter.voice = voice
    utter.lang = voice?.lang || "pt-BR"
    utter.rate = Math.min(2, Math.max(0.5, readSettings().tts.rate || 1))
    utter.onstart = () => {
      if (gen !== generation) return
      systemStart = performance.now()
      systemPausedTotal = 0
      setPhase("speaking")
      startSystemClock(gen)
      // Chromium can stop long utterances after ~15s; a no-op pause/resume
      // keeps the engine alive without cutting the text.
      systemKeepAlive = window.setInterval(() => {
        if (!window.speechSynthesis.speaking || window.speechSynthesis.paused) return
        window.speechSynthesis.pause()
        window.speechSynthesis.resume()
      }, 10_000)
    }
    utter.onend = () => {
      if (gen === generation) finish()
    }
    utter.onerror = (event) => {
      if (gen !== generation) return
      const code = (event as SpeechSynthesisErrorEvent).error
      if (code === "canceled" || code === "interrupted") return
      fail(ctx, new Error(code || "Speech synthesis failed"))
    }
    utterance = utter
    window.speechSynthesis.speak(utter)
  } catch (reason) {
    if (gen === generation) fail(ctx, reason)
  }
}

function pickSystemVoice(): SpeechSynthesisVoice | null {
  const voices = window.speechSynthesis.getVoices()
  if (!voices.length) return null
  const lang = (navigator.language || "pt-BR").toLowerCase().slice(0, 2)
  return (
    voices.find((voice) => voice.lang.toLowerCase().startsWith(lang)) ??
    voices.find((voice) => voice.lang.toLowerCase().startsWith("pt")) ??
    voices[0] ??
    null
  )
}

function startSystemClock(gen: number): void {
  if (clockRunning) return
  clockRunning = true
  const tick = () => {
    if (gen !== generation) {
      clockRunning = false
      return
    }
    if (phase() === "speaking") {
      const seconds = Math.max(0, (performance.now() - systemStart - systemPausedTotal) / 1000)
      setElapsed(seconds)
      const value = 0.25 + Math.abs(Math.sin(seconds * 7)) * 0.55
      bars.push({ value, start: seconds, end: seconds + 0.05 })
      if (bars.length > 200) bars = bars.slice(-200)
    }
    requestAnimationFrame(tick)
  }
  requestAnimationFrame(tick)
}

export function togglePause(): void {
  if (utterance) {
    if (phase() === "speaking") {
      window.speechSynthesis.pause()
      systemPausedAt = performance.now()
      setPhase("paused")
      return
    }
    if (phase() === "paused") {
      window.speechSynthesis.resume()
      systemPausedTotal += performance.now() - systemPausedAt
      setPhase("speaking")
      return
    }
  }
  const audio = audioEl
  if (!audio) {
    if (phase() === "error" && lastContext) void play(lastContext, lastText)
    return
  }
  if (phase() === "speaking") {
    audio.pause()
    setPhase("paused")
    return
  }
  if (phase() === "paused") {
    void audio.play().then(
      () => setPhase("speaking"),
      (reason) => fail(lastContext!, reason),
    )
    return
  }
  if (phase() === "error" && lastContext) {
    void play(lastContext, lastText)
  }
}

function startClock(gen: number): void {
  if (clockRunning) return
  clockRunning = true
  const levels = new Float32Array(256)
  const tick = () => {
    if (gen !== generation) {
      clockRunning = false
      return
    }
    const audio = audioEl
    if (!audio) {
      clockRunning = false
      return
    }
    setElapsed(audio.currentTime)
    if (Number.isFinite(audio.duration)) setTotal(audio.duration)
    if (analyser) {
      analyser.getFloatTimeDomainData(levels)
      let sum = 0
      for (const value of levels) sum += value * value
      const value = Math.min(1, Math.sqrt(sum / levels.length) * 4)
      bars.push({ value, start: audio.currentTime, end: audio.currentTime + 0.05 })
      if (bars.length > 200) bars = bars.slice(-200)
    } else {
      // No analyser (Web Audio would mute the WebView): animate from the
      // playback clock so the player still breathes while speaking.
      const seconds = audio.currentTime
      const envelope =
        0.34 +
        0.30 * Math.abs(Math.sin(seconds * 6.7)) +
        0.22 * Math.abs(Math.sin(seconds * 11.3 + 1.7)) * Math.abs(Math.cos(seconds * 2.1))
      const value = Math.min(1, envelope)
      bars.push({ value, start: seconds, end: seconds + 0.05 })
      if (bars.length > 200) bars = bars.slice(-200)
    }
    if (audio.ended) {
      finish()
      return
    }
    requestAnimationFrame(tick)
  }
  requestAnimationFrame(tick)
}

function finish(): void {
  generation++
  cancelStream()
  releaseLock()
  reset()
  setPhase("idle")
}

function fail(ctx: Context, reason: unknown): void {
  const message = describeError(reason)
  trace(ctx, `fail: ${message}`)
  controller?.abort()
  controller = null
  cancelStream()
  releaseLock()
  releaseAudio()
  setError(message)
  setPhase("error")
  ctx.toast.show({ title: `Read aloud failed: ${message}`, variant: "error" })
}
